import{_ as a,H as n,f as i,i as e}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"13 | 组件监控：MySQL的关键指标及采集方法有哪些？","description":"","frontmatter":{},"headers":[{"level":2,"title":"整体思路","slug":"整体思路","link":"#整体思路","children":[{"level":3,"title":"延迟","slug":"延迟","link":"#延迟","children":[]},{"level":3,"title":"流量","slug":"流量","link":"#流量","children":[]},{"level":3,"title":"错误","slug":"错误","link":"#错误","children":[]},{"level":3,"title":"饱和度","slug":"饱和度","link":"#饱和度","children":[]}]},{"level":2,"title":"采集配置","slug":"采集配置","link":"#采集配置","children":[{"level":3,"title":"中心化探测","slug":"中心化探测","link":"#中心化探测","children":[]},{"level":3,"title":"分布式本地采集","slug":"分布式本地采集","link":"#分布式本地采集","children":[]}]},{"level":2,"title":"业务指标","slug":"业务指标","link":"#业务指标","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"互动时刻","slug":"互动时刻","link":"#互动时刻","children":[]}],"relativePath":"运维监控系统实战笔记/13｜组件监控：MySQL的关键指标及采集方法有哪些？.md","filePath":"运维监控系统实战笔记/13｜组件监控：MySQL的关键指标及采集方法有哪些？.md","lastUpdated":1795561216000}'),p={name:"运维监控系统实战笔记/13｜组件监控：MySQL的关键指标及采集方法有哪些？.md"};function l(t,s,h,o,r,c){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="_13-组件监控-mysql的关键指标及采集方法有哪些" tabindex="-1">13 | 组件监控：MySQL的关键指标及采集方法有哪些？ <a class="header-anchor" href="#_13-组件监控-mysql的关键指标及采集方法有哪些" aria-label="Permalink to &quot;13 | 组件监控：MySQL的关键指标及采集方法有哪些？&quot;">​</a></h1><p>你好，我是秦晓辉。</p><p>按照第 9 讲介绍的监控分类方法，从这一讲开始，我们进入数据库中间件监控实战环节。这些组件里最常用的非 MySQL 莫属，这一讲我们就来介绍一下如何监控 MySQL。学完今天的内容之后，你就知道 MySQL 中哪些指标比较关键以及如何采集这些指标了。这些指标能够帮助我们提早发现问题，提升数据库的可用性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/13/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/13/1.png" alt=""></a></p><h2 id="整体思路" tabindex="-1">整体思路 <a class="header-anchor" href="#整体思路" aria-label="Permalink to &quot;整体思路&quot;">​</a></h2><p>在正式学习之前，我们要先理清两个问题：监控哪类指标？如何采集数据？这两个问题是不是还挺熟悉的，我们第 10 讲系统地介绍过监控方法论，这些方法论应该如何落地呢？这一讲，我们就可以在 MySQL 中应用起来。MySQL 是个服务，所以我们可以借用 Google 四个黄金指标的思路来解决问题。下面我们一起梳理一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/13/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/13/2.png" alt=""></a></p><h3 id="延迟" tabindex="-1">延迟 <a class="header-anchor" href="#延迟" aria-label="Permalink to &quot;延迟&quot;">​</a></h3><p>应用程序会向 MySQL 发起 SELECT、UPDATE 等操作，处理这些请求花费了多久，是非常关键的，甚至我们还想知道具体是哪个 SQL 最慢，这样就可以有针对性地调优。我们应该如何采集这些延迟数据呢？典型的方法有三种。</p><ol><li><p>在客户端埋点。即上层业务程序在请求 MySQL 的时候，记录一下每个 SQL 的请求耗时，把这些数据统一推给监控系统，监控系统就可以计算出平均延迟、95 分位、99 分位的延迟数据了。不过因为要埋点，对业务代码有一定侵入性。</p></li><li><p>Slow queries。MySQL 提供了慢查询数量的统计指标，通过下面这段命令就可以拿到。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>show global status like &#39;Slow_queries&#39;;</span></span>
<span class="line"><span>+---------------+-------+</span></span>
<span class="line"><span>| Variable_name | Value |</span></span>
<span class="line"><span>+---------------+-------+</span></span>
<span class="line"><span>| Slow_queries  | 107   |</span></span>
<span class="line"><span>+---------------+-------+</span></span>
<span class="line"><span>1 row in set (0.000 sec)</span></span></code></pre></div><p>这个指标是 Counter 类型的，即单调递增，如果想知道最近一分钟有多少慢查询，需要使用increase 函数做二次计算。</p><p>怎么算慢查询呢？实际是有一个全局变量的 long_query_time，默认是 10 秒，不过也可以调整。每当查询时间超过了 long_query_time 指定的时间，Slow_queries 就会 +1，我们可以通过下面这段命令获取 long_query_time 的值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SHOW VARIABLES LIKE &#39;long_query_time&#39;;</span></span>
<span class="line"><span>+-----------------+-----------+</span></span>
<span class="line"><span>| Variable_name   | Value     |</span></span>
<span class="line"><span>+-----------------+-----------+</span></span>
<span class="line"><span>| long_query_time | 10.000000 |</span></span>
<span class="line"><span>+-----------------+-----------+</span></span>
<span class="line"><span>1 row in set (0.001 sec)</span></span></code></pre></div><ol start="3"><li>通过 performance schema 和 sys schema 拿到统计数据。比如 performance schema 的events_statements_summary_by_digest 表，这个表捕获了很多关键信息，比如延迟、错误量、查询量。我们看下面的例子，SQL 执行了 2 次，平均执行时间是 325 毫秒，表里的时间度量指标都是以皮秒为单位。</li></ol><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">***************************</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">. </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">row</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ***************************</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">               SCHEMA_NAME: employees</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                    DIGEST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 0c6318da9de53353a3a1bacea70b4fce</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">               DIGEST_TEXT: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`employees\`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`emp_no\`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                COUNT_STAR: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            SUM_TIMER_WAIT: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">650358383000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            MIN_TIMER_WAIT: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">292045159000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            AVG_TIMER_WAIT: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">325179191000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            MAX_TIMER_WAIT: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">358313224000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             SUM_LOCK_TIME: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">520000000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                SUM_ERRORS: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">              SUM_WARNINGS: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         SUM_ROWS_AFFECTED: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             SUM_ROWS_SENT: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">520048</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         SUM_ROWS_EXAMINED: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">520048</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         SUM_NO_INDEX_USED: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SUM_NO_GOOD_INDEX_USED: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                FIRST_SEEN: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2016</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">03</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                 LAST_SEEN: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2016</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">03</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">55</span></span></code></pre></div><p>针对即时查询、诊断问题的场景，我们还可以使用 sys schema，sys schema 提供了一种组织良好、人类易读的指标查询方式，查询起来更简单。比如我们可以用下面的方法找到最慢的SQL。这个数据在 statements_with_runtimes_in_95th_percentile 表中。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sys</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">statements_with_runtimes_in_95th_percentile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>如果你想了解更多的例子，可以查看 sys schema 的文档。不过要注意的是，MySQL 从5.7.7 版本开始，才包含了 sys schema，好在从 5.6 版本开始可以手工安装。</p><h3 id="流量" tabindex="-1">流量 <a class="header-anchor" href="#流量" aria-label="Permalink to &quot;流量&quot;">​</a></h3><p>关于流量，我们最耳熟能详的是统计 SELECT、UPDATE、DELETE、INSERT 等语句执行的数量。如果流量太高，超过了硬件承载能力，显然是需要监控、需要扩容的。这些类型的指标在 MySQL 的全局变量中都可以拿到。我们来看下面这个例子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>show global status where Variable_name regexp &#39;Com_insert|Com_update|Com_delete|C</span></span>
<span class="line"><span>+-------------------------+-----------+</span></span>
<span class="line"><span>| Variable_name           | Value     |</span></span>
<span class="line"><span>+-------------------------+-----------+</span></span>
<span class="line"><span>| Com_delete              | 2091033   |</span></span>
<span class="line"><span>| Com_delete_multi        | 0         |</span></span>
<span class="line"><span>| Com_insert              | 8837007   |</span></span>
<span class="line"><span>| Com_insert_select       | 0         |</span></span>
<span class="line"><span>| Com_select              | 226099709 |</span></span>
<span class="line"><span>| Com_update              | 24218879  |</span></span>
<span class="line"><span>| Com_update_multi        | 0         |</span></span>
<span class="line"><span>| Empty_queries           | 25455182  |</span></span>
<span class="line"><span>| Qcache_queries_in_cache | 0         |</span></span>
<span class="line"><span>| Queries                 | 704921835 |</span></span>
<span class="line"><span>| Questions               | 461095549 |</span></span>
<span class="line"><span>| Slow_queries            | 107       |</span></span>
<span class="line"><span>+-------------------------+-----------+</span></span>
<span class="line"><span>12 rows in set (0.001 sec)</span></span></code></pre></div><p>例子中的这些指标都是 Counter 类型，单调递增，另外 Com_ 是 Command 的前缀，即各类命令的执行次数。整体吞吐量主要是看 Questions 指标，但 Questions 很容易和它上面的Queries 混淆。从例子里我们可以明显看出 Questions 的数量比 Queries 少。Questions 表示客户端发给 MySQL 的语句数量，而 Queries 还会包含在存储过程中执行的语句，以及PREPARE 这种准备语句，所以监控整体吞吐一般是看 Questions。</p><p>流量方面的指标，一般我们会统计写数量（Com_insert + Com_update + Com_delete）、读数量（Com_select）、语句总量（Questions）。</p><h3 id="错误" tabindex="-1">错误 <a class="header-anchor" href="#错误" aria-label="Permalink to &quot;错误&quot;">​</a></h3><p>错误量这类指标有多个应用场景，比如客户端连接 MySQL 失败了，或者语句发给 MySQL，执行的时候失败了，都需要有失败计数。典型的采集手段有两种。</p><ol><li><p>在客户端采集、埋点，不管是 MySQL 的问题还是网络的问题，亦或者中间负载均衡的问题或 DNS 解析的问题，只要连接失败了，都可以发现。缺点刚刚我们也介绍了，就是会有代码侵入性。</p></li><li><p>从 MySQL 中采集相关错误，比如连接错误可以通过 Aborted_connects 和Connection_errors_max_connections 拿到。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>show global status where Variable_name regexp &#39;Connection_errors_max_connections|</span></span>
<span class="line"><span>+-----------------------------------+--------+</span></span>
<span class="line"><span>| Variable_name                     | Value  |</span></span>
<span class="line"><span>+-----------------------------------+--------+</span></span>
<span class="line"><span>| Aborted_connects                  | 785546 |</span></span>
<span class="line"><span>| Connection_errors_max_connections | 0      |</span></span>
<span class="line"><span>+-----------------------------------+--------+</span></span></code></pre></div><p>只要连接失败，不管是什么原因，Aborted_connects 都会 +1，而更常用的是Connection_errors_max_connections ，它表示超过了最大连接数，所以 MySQL 拒绝连接。MySQL 默认的最大连接数只有 151，在现在这样的硬件条件下，实在是太小了，因此出现这种情况的频率比较高，需要我们多多关注，及时发现这一情况。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SHOW VARIABLES LIKE &#39;max_connections&#39;;</span></span>
<span class="line"><span>+-----------------+-------+</span></span>
<span class="line"><span>| Variable_name   | Value |</span></span>
<span class="line"><span>+-----------------+-------+</span></span>
<span class="line"><span>| max_connections | 151   |</span></span>
<span class="line"><span>+-----------------+-------+</span></span>
<span class="line"><span>1 row in set (0.001 sec)</span></span></code></pre></div><p>我们可以通过这个命令来调整最大连接数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET GLOBAL max_connections = 2048;</span></span></code></pre></div><p>虽然我们可以通过命令临时调整最大连接数，但一旦重启的话就失效了。为了永久修改这个配置，我们需要调整 my.cnf，在里面增加这么一行内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max_connections = 2048</span></span></code></pre></div><p>刚刚我们在介绍延迟指标的时候，提到了 events_statements_summary_by_digest 表，我们也可以通过这个表拿到错误数量。</p><p>举个例子。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> schema_name</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    , </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SUM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sum_errors) err_count</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> performance_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">events_statements_summary_by_digest</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> schema_name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS NOT NULL</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GROUP BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> schema_name;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--------------------+-----------+</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| schema_name        | err_count |</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--------------------+-----------+</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| employees          |         </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| performance_schema |         </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| sys                |         </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> |</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--------------------+-----------+</span></span></code></pre></div><h3 id="饱和度" tabindex="-1">饱和度 <a class="header-anchor" href="#饱和度" aria-label="Permalink to &quot;饱和度&quot;">​</a></h3><p>对于 MySQL 而言，用什么指标来反映资源有多“满”呢？首先我们要关注 MySQL 所在机器的CPU、内存、硬盘 I/O、网络流量这些基础指标，这些指标我们在第 11 讲机器监控中已经讲解过了，你可以自己再回顾一下。</p><p>MySQL 本身也有一些指标来反映饱和度，比如刚才我们讲到的连接数，当前连接数（Threads_connected）除以最大连接数（max_connections）可以得到连接数使用率，是一个需要重点监控的饱和度指标。</p><p>另外就是 InnoDB Buffer pool 相关的指标，一个是 Buffer pool 的使用率，一个是 Buffer pool的内存命中率。Buffer pool 是一块内存，专门用来缓存 Table、Index 相关的数据，提升查询性能。对 InnoDB 存储引擎而言，Buffer pool 是一个非常关键的设计。我们查看一下 Bufferpool 相关的指标。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MariaDB [(none)]&gt; show global status like &#39;%buffer%&#39;;</span></span>
<span class="line"><span>+---------------------------------------+----------------------------------------</span></span>
<span class="line"><span>| Variable_name                         | Value</span></span>
<span class="line"><span>+---------------------------------------+----------------------------------------</span></span>
<span class="line"><span>| Innodb_buffer_pool_dump_status        |</span></span>
<span class="line"><span>| Innodb_buffer_pool_load_status        | Buffer pool(s) load completed at 220825</span></span>
<span class="line"><span>| Innodb_buffer_pool_resize_status      |</span></span>
<span class="line"><span>| Innodb_buffer_pool_load_incomplete    | OFF</span></span>
<span class="line"><span>| Innodb_buffer_pool_pages_data         | 5837</span></span>
<span class="line"><span>| Innodb_buffer_pool_bytes_data         | 95633408</span></span>
<span class="line"><span>| Innodb_buffer_pool_pages_dirty        | 32</span></span>
<span class="line"><span>| Innodb_buffer_pool_bytes_dirty        | 524288</span></span>
<span class="line"><span>| Innodb_buffer_pool_pages_flushed      | 134640371</span></span>
<span class="line"><span>| Innodb_buffer_pool_pages_free         | 1036</span></span>
<span class="line"><span>| Innodb_buffer_pool_pages_misc         | 1318</span></span>
<span class="line"><span>| Innodb_buffer_pool_pages_total        | 8191</span></span>
<span class="line"><span>| Innodb_buffer_pool_read_ahead_rnd     | 0</span></span>
<span class="line"><span>| Innodb_buffer_pool_read_ahead         | 93316</span></span>
<span class="line"><span>| Innodb_buffer_pool_read_ahead_evicted | 203</span></span>
<span class="line"><span>| Innodb_buffer_pool_read_requests      | 8667876784</span></span>
<span class="line"><span>| Innodb_buffer_pool_reads              | 236654</span></span>
<span class="line"><span>| Innodb_buffer_pool_wait_free          | 5</span></span>
<span class="line"><span>| Innodb_buffer_pool_write_requests     | 533520851</span></span>
<span class="line"><span>+---------------------------------------+----------------------------------------</span></span>
<span class="line"><span>19 rows in set (0.001 sec)</span></span></code></pre></div><p>这里有 4 个指标我重点讲一下。Innodb_buffer_pool_pages_total 表示 InnoDB Buffer pool的页总量，页（page）是 Buffer pool 的一个分配单位，默认的 page size 是 16KiB，可以通</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>过  show variables like &quot;innodb_page_size&quot; 拿到。</span></span></code></pre></div><p>Innodb_buffer_pool_pages_free 是剩余页数量，通过 total 和 free 可以计算出 used，用used 除以 total 就可以得到使用率。当然，使用率高并不是说有问题，因为 InnoDB 有 LRU缓存清理机制，只要响应得够快，高使用率也不是问题。</p><p>Innodb_buffer_pool_read_requests 和 Innodb_buffer_pool_reads 是另外两个关键指标。read_requests 表示向 Buffer pool 发起的查询总量，如果 Buffer pool 缓存了相关数据直接返回就好，如果 Buffer pool 没有相关数据，就要穿透内存去查询硬盘了。有多少请求满足不了需要去查询硬盘呢？</p><p>这就要看 Innodb_buffer_pool_reads 指标统计的数量。所以，reads 这个指标除以read_requests 就得到了穿透比例，这个比例越高，性能越差，一般可以通过调整 Buffer pool的大小来解决。</p><p>根据 Google 四个黄金指标的方法论，我们梳理了 MySQL 相关的指标，这些指标大多是可以通过 global status 和 variables 拿到的。performance schema 和 sys schema 相对难搞，一是 sys schema 需要较高版本才能支持，二是这两个 schema 的数据不太适合放到 metrics 库里。常见做法是通过一些偏全局的统计指标，比如 Slow_queries，先发现问题，再通过这两个 schema 的数据分析细节。</p><p>不同的采集器采集的指标，命名方式会有差别，不过大同小异，关键是理解思路和原理。下面我们还是利用 Categraf 来配置采集，演示一下整个过程。</p><h2 id="采集配置" tabindex="-1">采集配置 <a class="header-anchor" href="#采集配置" aria-label="Permalink to &quot;采集配置&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Categraf 针对 MySQL 的采集插件配置，在 conf/input.mysql/mysql.toml 里。我准备</span></span></code></pre></div><p>了一个配置样例，你可以参考。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[[instances]]</span></span>
<span class="line"><span>address = &quot;127.0.0.1:3306&quot;</span></span>
<span class="line"><span>username = &quot;root&quot;</span></span>
<span class="line"><span>password = &quot;1234&quot;</span></span>
<span class="line"><span>extra_status_metrics = true</span></span>
<span class="line"><span>extra_innodb_metrics = true</span></span>
<span class="line"><span>gather_processlist_processes_by_state = false</span></span>
<span class="line"><span>gather_processlist_processes_by_user = false</span></span>
<span class="line"><span>gather_schema_size = false</span></span>
<span class="line"><span>gather_table_size = false</span></span>
<span class="line"><span>gather_system_table_size = false</span></span>
<span class="line"><span>gather_slave_status = true</span></span>
<span class="line"><span># # timeout</span></span>
<span class="line"><span># timeout_seconds = 3</span></span>
<span class="line"><span># labels = { instance=&quot;n9e-dev-mysql&quot; }</span></span></code></pre></div><p>最关键的配置是数据库连接地址和认证信息，具体采集哪些内容由一堆开关来控制。一般我建议把 extra_status_metrics、extra_innodb_metrics、gather_slave_status 设置为 true，其他的都不太需要采集。labels 部分，我建议你加个 instance 标签，给这个数据库取一个表意性更强的名称，未来收到告警消息的时候，可以一眼知道是哪个数据库的问题。instances 部分是个数组，如果要监控多个数据库，就配置多个 instances 就可以了。</p><p>Categraf 作为采集探针，采集 MySQL 时，有两种方案，一个是中心化探测方案，一个是分布式本地采集的方案。</p><h3 id="中心化探测" tabindex="-1">中心化探测 <a class="header-anchor" href="#中心化探测" aria-label="Permalink to &quot;中心化探测&quot;">​</a></h3><p>这个方案是专门找一台机器作为探针机器，部署一个单独的 Categraf，只用来采集 MySQL 相关的指标，同时采集所有的 MySQL 实例，即这个 Categraf 的 mysql.toml 中会有很多instances 配置段。</p><p>这种方案对 MySQL 实例数量较少以及云上的 RDS 服务的场景，都是适用的。不过相对不太方便做自动化，比如要新建一个 MySQL，还需要到这个探针机器里配置相关的采集规则，有一些麻烦。</p><h3 id="分布式本地采集" tabindex="-1">分布式本地采集 <a class="header-anchor" href="#分布式本地采集" aria-label="Permalink to &quot;分布式本地采集&quot;">​</a></h3><p>我个人更推荐第二种方案——分布式本地采集。这个方案是把 Categraf 部署到部署 MySQL的那台机器上，让 Categraf 采集 127.0.0.1:3306 的实例。对于 MySQL 这个服务，我建议不要混部，一台宿主机就部署一个 MySQL 就可以了，InnoDB Buffer pool 设置得大一些，80%物理内存，性能杠杠的。</p><p>DBA 管理 MySQL 的时候要经常创建集群，通常会沉淀出一些自动化工具，在自动化工具里把部署 Categraf、配置 Categraf 的 mysql.toml 的逻辑都加上，一键搞定，比较方便。监控只需要读权限，建议你 为监控系统创建一个单独的数据库账号，统一账号、统一密码、统一授权，这样 mysql.toml 的配置也比较一致。</p><p>采用这种部署方式的话，一般就用机器名做标识就可以了，不太需要单独的 instance 标签。Categraf 内置了一个夜莺监控大盘，大盘变量使用机器名来做过滤。如果你用的是Grafana，可以去 Grafana 官网搜一下 Dashboard，大同小异。注意一下，刚刚我们提到的那些关键指标，最好都要放到 Dashboard 里。效果图大概是这个样子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/13/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/13/3.png" alt=""></a></p><h2 id="业务指标" tabindex="-1">业务指标 <a class="header-anchor" href="#业务指标" aria-label="Permalink to &quot;业务指标&quot;">​</a></h2><p>MySQL 的指标采集，核心原理其实就是连上 MySQL 执行一些 SQL，查询性能数据。Categraf 内置了一些查询 SQL，那我们能否自定义一些 SQL，查询一些业务指标呢？比如查询一下业务系统的用户量，把用户量作为指标上报到监控系统，还是非常有价值的。第 9 讲我介绍过监控分类，其中最重要的一个类别，就是业务监控。</p><p>这个需求我们仍然可以使用 Categraf 的 MySQL 采集插件实现，查看 mysql.toml 里的默认配置，可以看到这样一段内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[[instances.queries]]</span></span></code></pre></div><p>这就是自定义 SQL 的配置，想要查询哪个数据库实例，就在对应的 [[instances]] 下面增加[[instances.queries]] 。我们看下这几个配置参数的解释。</p><ul><li><p>mesurement 指标类别，会作为 metric name 的前缀。</p></li><li><p>metric_fields 查询返回的结果，可能有多列是数值，指定哪些列作为指标上报。</p></li><li><p>label_fields 查询返回的结果，可能有多列是字符串，指定哪些列作为标签上报。</p></li><li><p>field_to_append 指定某一列的内容作为 metric name 的后缀。</p></li><li><p>timeout 语句执行超时时间。</p></li><li><p>request 查询语句，连续三个单引号，和 Python 的三个单引号语义类似，里边的内容就不用转义了。</p></li></ul><p>MySQL 相关的监控实践，包括性能监控和业务监控，核心就是上面我们说的这些内容，下面我们做一个总结。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>我们应用之前学过的 Google 四个黄金指标的方法论，来指导 MySQL 监控数据的采集，从延迟、流量、错误、饱和度四个方面分别讲解了具体的指标是什么以及如何获取这些指标。</p><p>采集器部署方面，我分享了两种典型的部署方案，实际上除了这两种，还有一种，就是容器环境下 Sidecar 模式。因为生产环境里 MySQL 一般很少放到容器里跑，所以这里没有提。另外，由于 MySQL 存储了很多业务数据，是业务指标的重要来源，通过自定义 SQL 可以获取很多业务指标，推荐你试用一下这种监控方式。</p><p>老规矩，我把这一讲的内容整理成了一张脑图，方便你理解和记忆。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/13/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/13/4.png" alt=""></a></p><h2 id="互动时刻" tabindex="-1">互动时刻 <a class="header-anchor" href="#互动时刻" aria-label="Permalink to &quot;互动时刻&quot;">​</a></h2><p>MySQL 的监控大盘，我们已经给出了，一些关键指标也点出来了，那告警规则应该怎么配置呢？常见的告警 PromQL 有哪些？欢迎你留言分享，也欢迎你把今天的内容分享给你身边的朋友，邀他一起学习。我们下一讲再见！</p>`,77)])])}const E=a(p,[["render",l]]);export{d as __pageData,E as default};
